	kinCousin      = int64(0)
	kinDisputed    = int64(1)
	kinInLaw       = int64(2)
	kinLatentKin   = int64(3)
	kinNeighbour   = int64(4)
	kinNotSpeaking = int64(5)
	kinRival       = int64(6)
	kinSibling     = int64(7)
	kinTakenIn     = int64(8)

