func TestPass_PaymentAndWithdraw(cur realm, t *testing.T) {
	adm := setup()
	p := ta("pass-buyer")
	price := PassPrice()
	testing.SetRealm(testing.NewUserRealm(p))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 1)})
	mustAbort(t, "underpay", revive(func() { ActivateGnomePass(cross(cur), 30) }), "attach exactly")
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", price*2)})
	mustAbort(t, "overpay", revive(func() { ActivateGnomePass(cross(cur), 30) }), "attach exactly")
	mustAbort(t, "bad duration", revive(func() { ActivateGnomePass(cross(cur), 45) }), "durationDays")
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", price)})
	ActivateGnomePass(cross(cur), 30)
	now := time.Now().Unix()
	if GnomePassExpiry(p.String()) != now+30*86400 {
		t.Errorf("expiry %d", GnomePassExpiry(p.String()))
	}
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", price*2)})
	ActivateGnomePass(cross(cur), 60) // stacks
	if GnomePassExpiry(p.String()) != now+90*86400 {
		t.Errorf("stacked expiry %d", GnomePassExpiry(p.String()))
	}
	if PassRevenue() != price*3 {
		t.Errorf("revenue %d", PassRevenue())
	}
	testing.SetOriginSend(nil)

	// Withdraw (the bank deposited the attached ugnot into the realm account).
	realmAddr := chain.PackageAddress(realmPkgPath)
	testing.IssueCoins(realmAddr, chain.Coins{chain.NewCoin("ugnot", price*3)})
	mustAbort(t, "non-admin withdraw", revive(func() { WithdrawFunds(cross(cur), p.String(), 1) }), "admin only")
	testing.SetRealm(testing.NewUserRealm(adm))
	out := ta("treasury-out")
	WithdrawFunds(cross(cur), out.String(), price*3)
	if TreasuryBalance() != 0 {
		t.Errorf("realm balance after withdraw %d", TreasuryBalance())
	}
	mustAbort(t, "overdraw", revive(func() { WithdrawFunds(cross(cur), out.String(), 1) }), "unwithdrawn pass revenue")
}

// TestWithdrawFunds_CannotExceedPassRevenue verifies that WithdrawFunds is
// strictly capped at passRevenueUgnot − adminGnotWithdrawn and cannot drain
// any ugnot that arrived through other means (e.g. donations or future
// features that hold player funds).
func TestWithdrawFunds_CannotExceedPassRevenue(cur realm, t *testing.T) {
	adm := setup()
	realmAddr := chain.PackageAddress(realmPkgPath)

	// Issue coins directly to the realm to simulate a "donation" beyond pass revenue.
	// passRevenueUgnot starts at 0 (no passes sold in this sub-test).
	donationAmount := int64(10000000) // 10 GNOT — not pass revenue
	testing.IssueCoins(realmAddr, chain.Coins{chain.NewCoin("ugnot", donationAmount)})

	// Admin must NOT be able to withdraw the donation — it exceeds pass revenue.
	testing.SetRealm(testing.NewUserRealm(adm))
	dst := ta("wd-dst")
	mustAbort(t, "withdraw donation beyond revenue",
		revive(func() { WithdrawFunds(cross(cur), dst.String(), 1) }),
		"unwithdrawn pass revenue")

	// Buy exactly one pass period so there is legitimate withdrawable revenue.
	price := PassPrice()
	buyer := ta("wd-buyer")
	testing.SetRealm(testing.NewUserRealm(buyer))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", price)})
	ActivateGnomePass(cross(cur), 30)
	testing.SetOriginSend(nil)
	testing.IssueCoins(realmAddr, chain.Coins{chain.NewCoin("ugnot", price)})

	// Withdrawing exactly the pass revenue must succeed.
	testing.SetRealm(testing.NewUserRealm(adm))
	WithdrawFunds(cross(cur), dst.String(), price)

	// A second withdraw of even 1 ugnot must fail (revenue exhausted).
	mustAbort(t, "second withdraw after full drain",
		revive(func() { WithdrawFunds(cross(cur), dst.String(), 1) }),
		"unwithdrawn pass revenue")

	// Withdrawable() must report 0.
	if got := WithdrawableFunds(); got != 0 {
		t.Errorf("WithdrawableFunds after drain = %d, want 0", got)
	}
}

// TestWithdrawProtocolFees_IsolatedFromCasinoAndPlayers verifies that
// WithdrawProtocolFees can only move the admin's own accrued share of
// protocol fees (adminFees[coin]) and cannot touch casinoPool or any player
// balance, even when those are substantially funded.
func TestWithdrawProtocolFees_IsolatedFromCasinoAndPlayers(cur realm, t *testing.T) {
	restore := exOpen()
	defer restore()

	adm := setup()
	player := ta("wpf-player")

	// Seed the player with coins and the casino pool with grin via accrueProtocolFee.
	give(player, "grin", 50000)
	casinoGrinBefore := getU(&casinoPool, "grin")

	// Accrue a known fee: accrueProtocolFee("grin", 200) splits 100 to adminFees,
	// 100 (or 99 due to integer div) to casinoPool.
	accrueProtocolFee("grin", 200)
	adminShare := getU(&adminFees, "grin")
	casinoShare := getU(&casinoPool, "grin") - casinoGrinBefore
	if adminShare == 0 {
		t.Fatal("expected non-zero adminFees after accrueProtocolFee")
	}

	// Non-admin must not be able to call WithdrawProtocolFees.
	testing.SetRealm(testing.NewUserRealm(player))
	mustAbort(t, "player fee withdraw",
		revive(func() { WithdrawProtocolFees(cross(cur), "grin") }),
		"admin only")

	// Snapshot player and casino balances before admin withdrawal.
	playerBalBefore := bal(player, "grin")
	casinoAfterAccrue := getU(&casinoPool, "grin")
	adminBalBefore := bal(adm, "grin")

	// Admin withdraws their protocol fees.
	testing.SetRealm(testing.NewUserRealm(adm))
	withdrawn := WithdrawProtocolFees(cross(cur), "grin")

	// Withdrawn amount must equal exactly the admin's accrued share.
	if withdrawn != adminShare {
		t.Errorf("withdrawn=%d, want adminShare=%d", withdrawn, adminShare)
	}

	// Admin balance must have increased by exactly withdrawn.
	if got := bal(adm, "grin"); got != adminBalBefore+withdrawn {
		t.Errorf("admin bal after = %d, want %d", got, adminBalBefore+withdrawn)
	}

	// Casino pool must be unchanged (not touched by the withdrawal).
	if got := getU(&casinoPool, "grin"); got != casinoAfterAccrue {
		t.Errorf("casinoPool after admin withdraw = %d, want %d (unchanged)", got, casinoAfterAccrue)
	}

	// Casino's incremental share must still be present.
	if casinoShare > 0 && getU(&casinoPool, "grin") < casinoGrinBefore+casinoShare {
		t.Errorf("casino lost coins during protocol fee withdrawal")
	}

	// Player balance must be unchanged.
	if got := bal(player, "grin"); got != playerBalBefore {
		t.Errorf("player bal after admin fee withdraw = %d, want %d (unchanged)", got, playerBalBefore)
	}

	// adminFees must now be zero for grin.
	if got := getU(&adminFees, "grin"); got != 0 {
		t.Errorf("adminFees[grin] after withdraw = %d, want 0", got)
	}

	// A second withdraw must panic (nothing to withdraw).
	mustAbort(t, "double withdraw",
		revive(func() { WithdrawProtocolFees(cross(cur), "grin") }),
		"no fees to withdraw")
}

