// ── PlayerXp ─────────────────────────────────────────────────────────────────

func TestPlayerXp_AccumulatesOnClaim(cur realm, t *testing.T) {
	setup()
	p := ta("xp-player")

	// Baseline: fresh player has 0 XP.
	if got := PlayerXp(p.String()); got != "0" {
		t.Errorf("initial XP want 0 got %s", got)
	}

	// Claim 10 grin (rarity 0 → 3 XP each) = 30 XP.
	payload := `[["grin","10"]]`
	n, e, s := voucher(t, "claim", p, payload)
	testing.SetRealm(testing.NewUserRealm(p))
	ClaimAndMint(cross(cur), payload, n, e, s)

	wantXp := uint64(10 * 3) // 10 coins × 3 XP (dust rarity)
	gotXp := getU(&playerXp, p.String())
	if gotXp != wantXp {
		t.Errorf("after grin claim: want XP %d got %d (PlayerXp=%s)", wantXp, gotXp, PlayerXp(p.String()))
	}

	// PlayerXp query must return the same value as a decimal string.
	if PlayerXp(p.String()) != strconv.FormatUint(wantXp, 10) {
		t.Errorf("PlayerXp query mismatch: want %d got %s", wantXp, PlayerXp(p.String()))
	}

	// Upgrade to stone tool (maxRarity=2) so the second claim can mine music.
	// Chain: hands → starter-twig → twig → wood → stone.
	testing.SetRealm(testing.NewUserRealm(p))
	for _, cost := range toolCosts["starter-twig"] {
		n, _ := strconv.ParseUint(cost[1], 10, 64)
		give(p, cost[0], n)
	}
	BuyTool(cross(cur), "starter-twig")
	for _, cost := range toolCosts["twig"] {
		n, _ := strconv.ParseUint(cost[1], 10, 64)
		give(p, cost[0], n)
	}
	BuyTool(cross(cur), "twig")
	for _, cost := range toolCosts["wood"] {
		n, _ := strconv.ParseUint(cost[1], 10, 64)
		give(p, cost[0], n)
	}
	BuyTool(cross(cur), "wood")
	for _, cost := range toolCosts["stone"] {
		n, _ := strconv.ParseUint(cost[1], 10, 64)
		give(p, cost[0], n)
	}
	BuyTool(cross(cur), "stone")

	// Second claim: add a higher-rarity coin. music is rarity 2 → 20 XP each.
	testing.SkipHeights(13) // skip cooldown
	payload2 := `[["music","5"]]`
	n2, e2, s2 := voucher(t, "claim", p, payload2)
	testing.SetRealm(testing.NewUserRealm(p))
	ClaimAndMint(cross(cur), payload2, n2, e2, s2)

	wantXp2 := wantXp + uint64(5*20) // +100 XP
	gotXp2 := getU(&playerXp, p.String())
	if gotXp2 != wantXp2 {
		t.Errorf("after music claim: want XP %d got %d", wantXp2, gotXp2)
	}

	// XP accumulates across players independently.
	q := ta("xp-q")
	if PlayerXp(q.String()) != "0" {
		t.Errorf("unrelated player should have 0 XP, got %s", PlayerXp(q.String()))
	}
}

package game32

import (
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"chain"
	"chain/banker"
)

func init(cur realm) {
	// The deployer (tx signer of addpkg) becomes admin and default operator.
	admin = address(cur.Previous().Address())
	operator = admin
}

// ── Roles ────────────────────────────────────────────────────────────────────

func isAdmin(cur realm) bool {
	return admin != address("") && cur.Previous().Address() == admin
}

func requireAdmin(cur realm) {
	if !isAdmin(cur) {
		panic("unauthorized: admin only")
	}
}


// TransferAdmin hands the admin role to another address.
func TransferAdmin(cur realm, newAdmin string) {
	requireAdmin(cur)
	transferAdmin(newAdmin)
}

func transferAdmin(newAdmin string) {
	a := address(newAdmin)
	if !a.IsValid() {
		panic("invalid address")
	}
	admin = a
}

// UpdateConfig is kept for game27/28 API compatibility (= TransferAdmin).
func UpdateConfig(cur realm, newAdmin string) {
	requireAdmin(cur)
	transferAdmin(newAdmin)
}


// SetClaimSigner registers the ed25519 public key (64 hex chars) of the
// server's claim signer. Pass "" to disable all vouchered calls (kill switch).
func SetClaimSigner(cur realm, pubKeyHex string) {
	requireAdmin(cur)
	if pubKeyHex == "" {
		claimSignerPubKey = nil
		return
	}
	b, err := hex.DecodeString(pubKeyHex)
	if err != nil || len(b) != 32 {
		panic("claim signer must be a 32-byte ed25519 public key in hex")
	}
	claimSignerPubKey = b
}

func ClaimSigner() string { return hex.EncodeToString(claimSignerPubKey) }
func Admin() string       { return admin.String() }

func SetPaused(cur realm, p bool) {
	requireAdmin(cur)
	paused = p
}

func IsPaused() bool { return paused }

func requireNotPaused() {
	if paused {
		panic("game is paused")
	}
}

// ── Blacklist ─────────────────────────────────────────────────────────────────

// BanAddress bans a player address. durationSecs=0 means permanent.
func BanAddress(cur realm, targetAddr string, reason string, durationSecs int64) {
	requireAdmin(cur)
	if !address(targetAddr).IsValid() {
		panic("invalid address")
	}
	expiry := int64(0)
	if durationSecs > 0 {
		expiry = time.Now().Unix() + durationSecs
	}
	blacklist.Set(targetAddr, strings.ReplaceAll(reason, ":", " ")+":"+strconv.FormatInt(time.Now().Unix(), 10))
	banExpiries.Set(targetAddr, strconv.FormatInt(expiry, 10))
}

func UnbanAddress(cur realm, targetAddr string) {
	requireAdmin(cur)
	blacklist.Remove(targetAddr)
	banExpiries.Remove(targetAddr)
}

func BlacklistStatus(addr string) string {
	if !blacklist.Has(addr) {
		return `{"banned":false}`
	}
	entry := blacklist.Get(addr).(string)
	expiry, _ := strconv.ParseInt(banExpiries.Get(addr).(string), 10, 64)
	now := time.Now().Unix()
	if expiry > 0 && now >= expiry {
		return `{"banned":false}`
	}
	reason := strings.SplitN(entry, ":", 2)[0]
	if expiry == 0 {
		return `{"banned":true,"reason":` + jsonStr(reason) + `,"permanent":true}`
	}
	return `{"banned":true,"reason":` + jsonStr(reason) + `,"permanent":false,"remainingSecs":` + strconv.FormatInt(expiry-now, 10) + `}`
}

func isBlacklisted(addr string) bool {
	if !blacklist.Has(addr) {
		return false
	}
	expiry, _ := strconv.ParseInt(banExpiries.Get(addr).(string), 10, 64)
	if expiry == 0 {
		return true
	}
	return time.Now().Unix() < expiry
}

func requirePlayer(cur realm) string {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	if isBlacklisted(caller) {
		panic("address banned")
	}
	return caller
}

// ── Veins ────────────────────────────────────────────────────────────────────

func veinMax(coinId string) uint64 {
	// FIX 2B: skip AVL read when no overrides have ever been set.
	if veinOverrideActive && veinMaxOverride.Has(coinId) {
		v, _ := strconv.ParseUint(veinMaxOverride.Get(coinId).(string), 10, 64)
		return v
	}
	r, ok := coinRarity[coinId]
	if !ok {
		return 0
	}
	if v, ok := veinCoinDefault[coinId]; ok {
		return v
	}
	return veinDefaultMax[r]
}

func veinMintedOf(coinId string) uint64 {
	if !veinMinted.Has(coinId) {
		return 0
	}
	v, _ := strconv.ParseUint(veinMinted.Get(coinId).(string), 10, 64)
	return v
}

// takeFromVein returns how much of amt can still be minted for coinId and
// records it as minted.
func takeFromVein(coinId string, amt uint64) uint64 {
	mx := veinMax(coinId)
	mi := veinMintedOf(coinId)
	if mi >= mx {
		return 0
	}
	if amt > mx-mi {
		amt = mx - mi
	}
	veinMinted.Set(coinId, strconv.FormatUint(mi+amt, 10))
	if half := mx / 2; mi < half && mi+amt >= half {
		chain.Emit("VeinHalfMinted", "coin", coinId,
			"minted", strconv.FormatUint(mi+amt, 10), "max", strconv.FormatUint(mx, 10))
	}
	if mi+amt == mx {
		chain.Emit("VeinExhausted", "coin", coinId, "max", strconv.FormatUint(mx, 10))
	}
	return amt
}

// SetVeinMax overrides a coin's vein size. It can't go below what was minted.
func SetVeinMax(cur realm, coinId string, maxSupply string) {
	requireAdmin(cur)
	setVeinMax(coinId, maxSupply)
}

func setVeinMax(coinId string, maxSupply string) {
	if _, ok := coinRarity[coinId]; !ok {
		panic("unknown coin id: " + coinId)
	}
	mx, err := strconv.ParseUint(maxSupply, 10, 64)
	if err != nil {
		panic("invalid max supply")
	}
	if mx < veinMintedOf(coinId) {
		panic("vein max below already-minted supply")
	}
	veinMaxOverride.Set(coinId, strconv.FormatUint(mx, 10))
	veinOverrideActive = true
}

// RegisterVein is the game28 name for SetVeinMax.
func RegisterVein(cur realm, coinId string, maxSupply string) {
	requireAdmin(cur)
	setVeinMax(coinId, maxSupply)
}

func VeinSupply(coinId string) string {
	if _, ok := coinRarity[coinId]; !ok {
		return `{"remaining":"0","max":"0"}`
	}
	mx := veinMax(coinId)
	mi := veinMintedOf(coinId)
	rem := uint64(0)
	if mx > mi {
		rem = mx - mi
	}
	return `{"remaining":"` + strconv.FormatUint(rem, 10) + `","max":"` + strconv.FormatUint(mx, 10) + `","minted":"` + strconv.FormatUint(mi, 10) + `","halfMinted":` + strconv.FormatBool(mx > 0 && mi >= mx/2) + `,"exhausted":` + strconv.FormatBool(mx > 0 && mi >= mx) + `}`
}

// ── Gnome Pass (paid) ────────────────────────────────────────────────────────

// SetPassPrice sets the ugnot price per 30-day period.
func SetPassPrice(cur realm, ugnotPer30Days int64) {
	requireAdmin(cur)
	if ugnotPer30Days <= 0 {
		panic("price must be > 0")
	}
	passPriceUgnot = ugnotPer30Days
}

func PassPrice() int64 { return passPriceUgnot }

// ActivateGnomePass buys durationDays (30..360, multiple of 30) of Gnome Pass.
// The tx must attach exactly passPrice × durationDays/30 ugnot (MsgCall send).
func ActivateGnomePass(cur realm, durationDays int64) {
	caller := requirePlayer(cur)
	// Payment verification must only trust the origin envelope when the
	// caller is the signer itself (no intermediate realm can consume it).
	if cur.Previous().PkgPath() != "" {
		panic("Gnome Pass must be bought directly by the player")
	}
	if durationDays <= 0 || durationDays%30 != 0 || durationDays > 360 {
		panic("durationDays must be 30, 60, ... 360")
	}
	periods := durationDays / 30
	required := passPriceUgnot * periods
	sent := banker.NewBanker(banker.BankerTypeOriginSend, cur).GetCoins(cur.Address())
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != required {
		panic("Gnome Pass costs " + strconv.FormatInt(required, 10) + "ugnot for " + strconv.FormatInt(durationDays, 10) + " days — attach exactly that amount")
	}
	passRevenueUgnot += required

	now := time.Now().Unix()
	base := now
	if gnomePasses.Has(caller) {
		existing, _ := strconv.ParseInt(gnomePasses.Get(caller).(string), 10, 64)
		if existing > now {
			base = existing
		}
	}
	gnomePasses.Set(caller, strconv.FormatInt(base+durationDays*86400, 10))
}

func GnomePassExpiry(addr string) int64 {
	if !gnomePasses.Has(addr) {
		return 0
	}
	expiry, _ := strconv.ParseInt(gnomePasses.Get(addr).(string), 10, 64)
	return expiry
}

func HasActivePass(addr string) bool { return GnomePassExpiry(addr) > time.Now().Unix() }

func GnomePassCount() int {
	count := 0
	now := time.Now().Unix()
	gnomePasses.Iterate("", "", func(_ string, val any) bool {
		e, _ := strconv.ParseInt(val.(string), 10, 64)
		if e > now {
			count++
		}
		return false
	})
	return count
}

func PassRevenue() int64 { return passRevenueUgnot }

// TreasuryBalance returns the ugnot held by this realm (pass revenue not yet withdrawn).
func TreasuryBalance(cur realm) int64 {
	realmAddr := chain.PackageAddress("gno.land/r/g138gdmwj6heduu3st796lw6qqdwylgaxf7ty5gz/game32")
	coins := banker.NewBanker(banker.BankerTypeReadonly, cur).GetCoins(realmAddr)
	for _, c := range coins {
		if c.Denom == "ugnot" {
			return c.Amount
		}
	}
	return 0
}

// WithdrawFunds sends GNOT the admin is OWED — Gnome Pass revenue not yet
// withdrawn — to `to`. It can never touch other ugnot the realm holds
// (donations, anything a future feature would hold for players).
func WithdrawFunds(cur realm, to string, amountUgnot int64) {
	requireAdmin(cur)
	dst := address(to)
	if !dst.IsValid() {
		panic("invalid address")
	}
	if amountUgnot <= 0 {
		panic("amount must be > 0")
	}
	if amountUgnot > passRevenueUgnot-adminGnotWithdrawn {
		panic("can only withdraw unwithdrawn pass revenue: " + strconv.FormatInt(passRevenueUgnot-adminGnotWithdrawn, 10) + "ugnot")
	}
	adminGnotWithdrawn += amountUgnot
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), dst, chain.Coins{chain.NewCoin("ugnot", amountUgnot)})
	chain.Emit("FundsWithdrawn", "to", to, "ugnot", strconv.FormatInt(amountUgnot, 10))
}

// WithdrawableFunds = pass revenue the admin may still withdraw (ugnot).
func WithdrawableFunds() int64 { return passRevenueUgnot - adminGnotWithdrawn }

// ── Migration (game31 → game32) ──────────────────────────────────────────────
//
// MigrateBatch(batchId, kind, rowsJson) imports one batch. rowsJson is a JSON
// array of string arrays. Kinds and row shapes:
//   balance  [addr, coinId, amount]       → balances (SET, not add)
//   lifetime [addr, coinId, amount]       → lifetimeMined (SET) + miners total
//   tools    [addr, "t1,t2,..."]          → ownedTools (SET, unknown ids dropped)
//   toollife [addr, toolId, life]         → toolLife (SET, clamped to max)
//   skill    [addr, skillId, rank]        → skillRanks (SET, clamped to max)
//   medal    [addr, achievementId]        → achievements (allowlisted ids only)
//   pass     [addr, expiryUnix]           → gnomePasses (SET)
//   guild    [guildId, name, leader, "m1,m2,..."] → guilds + members
//   ban      [addr, reason, expiryUnix]   → blacklist (expiry 0 = permanent)
// A batchId that was already applied is skipped, and every write is a SET, so
// re-running a whole migration is a no-op. FinalizeMigration locks it forever.
// Every unique player address in a batch is recorded in migrationAddrs so that
// MigrationStatus can report how many distinct players were migrated.
func MigrateBatch(cur realm, batchId string, kind string, rowsJson string) int {
	requireAdmin(cur)
	if migrationFinalized {
		panic("migration is finalized")
	}
	if batchId == "" {
		panic("batchId required")
	}
	if migrationBatches.Has(batchId) {
		return 0
	}
	rows := parseStringRows(rowsJson)
	n := 0
	for _, r := range rows {
		if migrateRow(kind, r) {
			n++
			// Track the player address for the migrated-count in MigrationStatus.
			// For player-scoped kinds the address is always r[0]; guild rows use a
			// guild ID, not a player address, so we skip them.
			if kind != "guild" && len(r) > 0 && validAddr(r[0]) {
				migrationAddrs.Set(r[0], "1")
			}
		}
	}
	migrationBatches.Set(batchId, kind+":"+strconv.Itoa(n))
	return n
}

func FinalizeMigration(cur realm) {
	requireAdmin(cur)
	migrationFinalized = true
}

// MigrationStatus returns a JSON object with:
//   - finalized: bool   — true once FinalizeMigration has been called
//   - batches:   int    — number of distinct batch IDs applied
//   - addresses: int    — number of distinct player addresses migrated across all batches
func MigrationStatus() string {
	return `{"finalized":` + strconv.FormatBool(migrationFinalized) +
		`,"batches":` + strconv.Itoa(migrationBatches.Size()) +
		`,"addresses":` + strconv.Itoa(migrationAddrs.Size()) + `}`
}

func MigrationBatch(batchId string) string {
	if !migrationBatches.Has(batchId) {
		return ""
	}
	return migrationBatches.Get(batchId).(string)
}

func validAddr(s string) bool { return address(s).IsValid() }

func migrateRow(kind string, r []string) bool {
	switch kind {
	case "balance", "lifetime":
		if len(r) != 3 || !validAddr(r[0]) {
			return false
		}
		if _, ok := coinRarity[r[1]]; !ok {
			return false
		}
		amt, err := strconv.ParseUint(r[2], 10, 64)
		if err != nil {
			return false
		}
		key := r[0] + ":" + r[1]
		if kind == "balance" {
			old := getU(&balances, key)
			// Imported balances count against the vein (delta on re-run).
			if amt > old {
				mi := veinMintedOf(r[1])
				veinMinted.Set(r[1], strconv.FormatUint(mi+(amt-old), 10))
			}
			setU(&balances, key, amt)
		} else {
			old := getU(&lifetimeMined, key)
			setU(&lifetimeMined, key, amt)
			tot := getU(&miners, r[0])
			if tot >= old {
				tot -= old
			} else {
				tot = 0
			}
			setU(&miners, r[0], tot+amt)
		}
		return true
	case "tools":
		if len(r) != 2 || !validAddr(r[0]) {
			return false
		}
		var keep []string
		seen := map[string]bool{}
		for _, t := range strings.Split(r[1], ",") {
			t = strings.TrimSpace(t)
			if t == "" || t == "hands" || seen[t] {
				continue
			}
			if _, ok := toolCosts[t]; !ok {
				continue
			}
			seen[t] = true
			keep = append(keep, t)
		}
		if len(keep) == 0 {
			ownedTools.Remove(r[0])
		} else {
			ownedTools.Set(r[0], strings.Join(keep, ","))
		}
		return true
	case "toollife":
		if len(r) != 3 || !validAddr(r[0]) {
			return false
		}
		mx, ok := toolMaxLife[r[1]]
		if !ok || mx == 0 {
			return false
		}
		life, err := strconv.ParseUint(r[2], 10, 64)
		if err != nil {
			return false
		}
		if em := effectiveMaxLife(r[0], r[1]); life > em {
			life = em
		}
		setU(&toolLife, r[0]+":"+r[1], life)
		return true
	case "skill":
		if len(r) != 3 || !validAddr(r[0]) {
			return false
		}
		mx, ok := skillMaxRanks[r[1]]
		if !ok {
			return false
		}
		rank, err := strconv.ParseUint(r[2], 10, 64)
		if err != nil {
			return false
		}
		if rank > mx {
			rank = mx
		}
		setU(&skillRanks, r[0]+":"+r[1], rank)
		return true
	case "medal":
		if len(r) != 2 || !validAddr(r[0]) || !isValidAchievementId(r[1]) {
			return false
		}
		achievements.Set(r[0]+":"+r[1], "1")
		return true
	case "pass":
		if len(r) != 2 || !validAddr(r[0]) {
			return false
		}
		e, err := strconv.ParseInt(r[1], 10, 64)
		if err != nil || e <= 0 {
			return false
		}
		gnomePasses.Set(r[0], strconv.FormatInt(e, 10))
		return true
	case "guild":
		if len(r) != 4 || r[0] == "" || !validAddr(r[2]) {
			return false
		}
		name := sanitizeName(r[1])
		if len(name) < 3 {
			return false
		}
		members := []string{}
		for _, m := range strings.Split(r[3], ",") {
			m = strings.TrimSpace(m)
			if validAddr(m) && len(members) < maxGuildMembers {
				members = append(members, m)
			}
		}
		if len(members) == 0 {
			return false
		}
		// Drop stale membership rows of this guild, then write fresh ones.
		var stale []string
		guildMembers.Iterate(r[0]+":", r[0]+";", func(k string, _ any) bool {
			stale = append(stale, k)
			return false
		})
		for _, k := range stale {
			guildMembers.Remove(k)
		}
		for _, m := range members {
			guildMembers.Set(r[0]+":"+m, "1")
			playerGuild.Set(m, r[0])
		}
		guildMetas[r[0]] = guildMeta{name: name, leader: r[2], createdAt: time.Now().Unix()}
		rewriteGuild(r[0])
		return true
	case "ban":
		if len(r) != 3 || !validAddr(r[0]) {
			return false
		}
		e, err := strconv.ParseInt(r[2], 10, 64)
		if err != nil || e < 0 {
			return false
		}
		blacklist.Set(r[0], strings.ReplaceAll(r[1], ":", " ")+":"+strconv.FormatInt(time.Now().Unix(), 10))
		banExpiries.Set(r[0], strconv.FormatInt(e, 10))
		return true
	}
	panic("unknown migration kind: " + kind)
}

package game32

import (
	"crypto/sha256"
	"encoding/hex"
	"math/bits"
	"strconv"
	"strings"
	"time"

	"chain"

	"gno.land/p/nt/avl/v0"
)

// ── Casino: two-sided commit–reveal, settled and paid on chain ──────────────
//
// One round = one bet by one player:
//   1. CommitCasinoSeed(roundId, player, sha256(s))        operator
//        s is 32 fresh random bytes for this round, kept by the server.
//   2. PlaceCasinoBet(roundId, game, coin, amt, choice, sha256(c))   the player
//        c is the player's secret (made and kept by the browser). The stake is
//        debited and the bet's largest possible net win is reserved in the pool.
//   3. RevealCasinoSeed(roundId, s)                        operator
//        s must hash to the commit. The operator still doesn't know c, so it
//        doesn't know the result when it reveals.
//   4. RevealCasinoSecret(roundId, c)                      anyone (a preimage)
//        c must hash to the bet's hash; the realm rolls and settles the bet.
// Timeouts (nobody can profit from withholding):
//   - s not revealed 30 min after the bet → RefundCasinoBet (full stake back).
//   - s revealed but c not revealed within 24 h → ForfeitCasinoBet (anyone):
//     the bet settles as a loss; only the player could have known the result.
//   No refund once s is revealed.
//
// Results (the only rules; the client re-derives and shows them):
//   roll = uint32(sha256(s:c:roundId:game)[0:4]) % 100
//   coin_flip:    0..48 heads, 51..99 tails, 49/50 edge (house)      win pays 2×
//   higher_lower: 51..99 higher, 0..48 lower, 49/50 house              win pays 2×
//   rps:          0..32 player wins (2×), 33..64 push (stake back), 65..99 house
//                 wins; the house move shown is derived from that. RTP 98%.
//   slots:        reels/lines/scatters/Hold & Spin from the stream in game_slots.gno;
//                 free spins and MAJOR/GRAND jackpots in game_casino_bonus.gno.
//
// Pool safety (fixed in code):
//   coin_flip / wheel / rps bet ≤ 0.5% of the free pool; slots bet ≤ 0.004%
//   (its 500× max win then reserves ≤ 2% of the pool); every open bet reserves
//   its largest net win; open reservations ≤ 20% of the pool; net paid today +
//   reservations ≤ 10% of the pool at 00:00 UTC; opens at ≥ 20,000 grin-eq and
//   ≥ 200 units. Coins only move between players and the pool: nothing is
//   minted, and the admin can't withdraw the pool.

var (
	casinoBets     avl.Tree // roundId+":"+addr → *casinoBet
	casinoReserved avl.Tree // coin → largest net payouts of unsettled bets (string)
	casinoDay      avl.Tree // coin → "day:snapshot:paid:received" (UTC day)
)

const (
	casinoWinRange         = uint64(49)       // winning rolls per pick (of 100) for flip/wheel
	rpsWinBelow            = uint64(33)       // rps: roll < 33 player wins
	rpsPushBelow           = uint64(65)       // rps: 33..64 push
	casinoBetWindowSec     = int64(3600)      // a committed round takes its bet within 1 h
	casinoSeedTimeoutSec   = int64(1800)      // refunds open 30 min after the bet if s is never revealed
	casinoSecretTimeoutSec = int64(86400)     // the bet forfeits 24 h after s if c is never revealed
	casinoMaxBetBps        = uint64(50)       // flip / wheel / rps bet ≤ 0.5% of the free pool
	slotsMaxBetPPM         = uint64(40)       // slots bet ≤ 0.004% of the free pool
	casinoOpenBps          = uint64(2000)     // open reservations on a coin ≤ 20% of the pool
	casinoDayBps           = uint64(1000)     // daily net payout ≤ 10% of the day's snapshot
	casinoMinPoolMilli     = uint64(20000000) // ≥ 20,000 grin-equivalent …
	casinoMinPoolUnits     = uint64(200)      // … and ≥ 200 units of the coin
	casinoMaxAmount        = uint64(1000000000)
)

// Reference value per unit by rarity, in milli-grin (same table as the
// exchange plan): only used for the pool's opening threshold.
var casinoRefMilli = [7]uint64{1000, 3200, 11000, 40000, 160000, 720000, 3600000}

type casinoRound struct {
	player      string
	seedHash    string
	serverSeed  string
	status      string // committed | bet | seeded | settled | refunded | closed
	committedAt int64
	betAt       int64
	seededAt    int64
	bets        int
}

type casinoBet struct {
	addr, game, coin, choice string
	clientHash, clientSecret string
	amount, exposure         uint64
	settled, won, refunded   bool
	forfeited                bool
	roll, payout             uint64
	outcome                  string
	// slots only
	grid       string
	lineMult   uint64
	lines      int
	scatters   int
	freeSpin   bool   // a free spin from a grant (no stake)
	capped     bool   // the round's win hit the 500× cap
	fsGranted  uint64 // free spins this spin granted
	hsTiles    string // Hold & Spin tiles ("." separated, 0 = empty)
	hsRespins  int
	hsMult     uint64 // Hold & Spin win in bets (MINI/MINOR included)
	jackpots   string // "major", "grand", "major+grand" or ""
	jackpotWin uint64 // paid from the jackpot pools (outside the cap)
}

// ── roles ────────────────────────────────────────────────────────────────────

// isOperator: the casino operator key commits and reveals server seeds. Once an
// operator is set, only that key can; the admin (treasury) key only stands in
// while no operator has been named yet (bootstrap and tests).
func isOperator(cur realm) bool {
	c := cur.Previous().Address()
	if operator != address("") {
		return c == operator
	}
	return admin != address("") && c == admin
}

// SetOperator lets the admin name the server account that commits and
// reveals casino seeds. It must be its own key, never the admin/treasury key.
// The operator can't move anyone's coins.
func SetOperator(cur realm, addr string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	a := address(addr)
	if !a.IsValid() {
		panic("invalid address")
	}
	if a == admin {
		panic("the casino operator must be a separate key, not the admin/treasury key")
	}
	operator = a
	chain.Emit("CasinoOperatorSet", "operator", addr)
}

func Operator() string { return operator.String() }

// ── casino accounting (monitoring) ──────────────────────────────────────────
//
// Per coin: pool + MAJOR + GRAND == seeded + staked − paid, always. Per coin and
// game: rounds, staked, paid (free spins and jackpots count as slots pay), so
// realized RTP = paid / staked. Updated on every settlement; read by CasinoStats.

var casinoStats avl.Tree // coin:field or coin:game:field → uint (string)

func casStat(coin, game, field string, add uint64) {
	k := coin + ":" + field
	if game != "" {
		k = coin + ":" + game + ":" + field
	}
	casSet(&casinoStats, k, casAdd(casGet(&casinoStats, k), add))
}

func casRecord(coin, game string, staked, paid uint64) {
	casStat(coin, game, "rounds", 1)
	casStat(coin, game, "staked", staked)
	casStat(coin, game, "paid", paid)
	casStat(coin, "", "staked", staked)
	casStat(coin, "", "paid", paid)
}

// CasinoStats reports a coin's accounting: pool, reserved, jackpots, seeded,
// staked, paid, the conservation check and per-game rounds/staked/paid.
func CasinoStats(coinId string) string {
	pool := casGet(&casinoPool, coinId)
	major := casGet(&casinoJackpot, jpKey(coinId, "major"))
	grand := casGet(&casinoJackpot, jpKey(coinId, "grand"))
	seeded := casGet(&casinoStats, coinId+":seeded")
	staked := casGet(&casinoStats, coinId+":staked")
	paid := casGet(&casinoStats, coinId+":paid")
	fees := casGet(&casinoStats, coinId+":fees") // exchange protocol-fee inflow
	ok := pool+major+grand+paid == seeded+staked+fees
	out := `{"coin":"` + coinId + `","pool":"` + casU(pool) + `","reserved":"` + casU(casGet(&casinoReserved, coinId)) +
		`","major":"` + casU(major) + `","grand":"` + casU(grand) + `","seeded":"` + casU(seeded) +
		`","staked":"` + casU(staked) + `","paid":"` + casU(paid) + `","fees":"` + casU(fees) + `","conserved":` + strconv.FormatBool(ok) +
		`,"freeSpinsOpen":` + strconv.Itoa(casinoGrants.Size()) + `,"games":{`
	for i, g := range []string{"coin_flip", "higher_lower", "rps", "slots"} {
		if i > 0 {
			out += ","
		}
		out += `"` + g + `":{"rounds":` + casU(casGet(&casinoStats, coinId+":"+g+":rounds")) +
			`,"staked":"` + casU(casGet(&casinoStats, coinId+":"+g+":staked")) +
			`","paid":"` + casU(casGet(&casinoStats, coinId+":"+g+":paid")) + `"}`
	}
	return out + `}}`
}

// ── uint helpers (balances and pool values are decimal strings) ─────────────

func casGet(t *avl.Tree, key string) uint64 {
	if !t.Has(key) {
		return 0
	}
	v, _ := strconv.ParseUint(t.Get(key).(string), 10, 64)
	return v
}

func casSet(t *avl.Tree, key string, v uint64) { t.Set(key, strconv.FormatUint(v, 10)) }

func casAdd(a, b uint64) uint64 {
	s, carry := bits.Add64(a, b, 0)
	if carry != 0 {
		panic("math overflow")
	}
	return s
}

func casSub(a, b uint64) uint64 {
	if b > a {
		panic("math underflow")
	}
	return a - b
}

// casMulDiv = floor(a*b/c) with a 128-bit product.
func casMulDiv(a, b, c uint64) uint64 {
	hi, lo := bits.Mul64(a, b)
	if hi >= c {
		panic("math overflow")
	}
	q, _ := bits.Div64(hi, lo, c)
	return q
}

func casMul(a, b uint64) uint64 {
	hi, lo := bits.Mul64(a, b)
	if hi != 0 {
		panic("math overflow")
	}
	return lo
}

func casU(n uint64) string { return strconv.FormatUint(n, 10) }

func casBalOf(addr, coin string) uint64 { return casGet(&balances, addr+":"+coin) }

func casCredit(addr, coin string, amt uint64) {
	if amt > 0 {
		casSet(&balances, addr+":"+coin, casAdd(casBalOf(addr, coin), amt))
	}
}

func casDebit(addr, coin string, amt uint64) {
	have := casBalOf(addr, coin)
	if have < amt {
		panic("insufficient balance: need " + casU(amt) + " " + coin + ", have " + casU(have))
	}
	casSet(&balances, addr+":"+coin, have-amt)
}

func casGrinValueMilli(coin string, amt uint64) uint64 {
	r, ok := coinRarity[coin]
	if !ok || r < 0 || r > 6 {
		return 0
	}
	hi, lo := bits.Mul64(amt, casinoRefMilli[r])
	if hi != 0 {
		return ^uint64(0)
	}
	return lo
}

func casIsHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// casSafe: a short [A-Za-z0-9_.-] token (no quotes, so it is JSON-safe).
func casSafe(s string, maxLen int) bool {
	if s == "" || len(s) > maxLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '-' || c == '_' || c == '.') {
			return false
		}
	}
	return true
}

func sha256Hex(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

// ── outcome rules (the only ones; the client just re-derives them) ──────────

// CasinoRoll is the on-chain roll: uint32(sha256(s:c:roundId:game)[0:4]) % 100.
func CasinoRoll(serverSeed, clientSecret, roundId, game string) uint64 {
	h := sha256.Sum256([]byte(serverSeed + ":" + clientSecret + ":" + roundId + ":" + game))
	v := uint64(h[0])<<24 | uint64(h[1])<<16 | uint64(h[2])<<8 | uint64(h[3])
	return v % 100
}

// CasinoOutcome maps a roll to what landed. For rps the outcome is
// "win" | "push" | "lose" (see rpsHouseMove for the move shown).
func CasinoOutcome(game string, roll uint64) string {
	switch game {
	case "coin_flip":
		if roll < casinoWinRange {
			return "heads"
		}
		if roll >= 100-casinoWinRange {
			return "tails"
		}
		return "edge"
	case "higher_lower":
		if roll >= 100-casinoWinRange {
			return "higher"
		}
		if roll < casinoWinRange {
			return "lower"
		}
		return "house"
	case "rps":
		if roll < rpsWinBelow {
			return "win"
		}
		if roll < rpsPushBelow {
			return "push"
		}
		return "lose"
	}
	return ""
}

// rpsHouseMove: the house move that produces the outcome against the player's move.
func rpsHouseMove(choice, outcome string) string {
	beats := map[string]string{"rock": "scissors", "paper": "rock", "scissors": "paper"} // key beats value
	switch outcome {
	case "win":
		return beats[choice]
	case "push":
		return choice
	}
	for k, v := range beats {
		if v == choice {
			return k
		}
	}
	return ""
}

func validCasinoChoice(game, choice string) bool {
	switch game {
	case "coin_flip":
		return choice == "heads" || choice == "tails"
	case "higher_lower":
		return choice == "higher" || choice == "lower"
	case "rps":
		return choice == "rock" || choice == "paper" || choice == "scissors"
	case "slots":
		return casSafe(choice, 32)
	}
	return false
}

// casinoExposure: the largest net amount a bet can take from the pool.
func casinoExposure(game string, amt uint64) uint64 {
	if game == "slots" {
		return casMul(amt, slotsMaxWinMult-1)
	}
	return amt // flip / wheel / rps win pays 2× = net +amt
}

// ── pool ────────────────────────────────────────────────────────────────────

func casDayNow() int64 { return time.Now().Unix() / 86400 }

func casinoDayState(coin string) (int64, uint64, uint64, uint64) {
	day := casDayNow()
	if casinoDay.Has(coin) {
		f := strings.Split(casinoDay.Get(coin).(string), ":")
		d, _ := strconv.ParseInt(f[0], 10, 64)
		if d == day && len(f) == 4 {
			snap, _ := strconv.ParseUint(f[1], 10, 64)
			paid, _ := strconv.ParseUint(f[2], 10, 64)
			recv, _ := strconv.ParseUint(f[3], 10, 64)
			return day, snap, paid, recv
		}
	}
	return day, casGet(&casinoPool, coin), 0, 0 // first touch of the day: snapshot the pool
}

func setCasinoDay(coin string, day int64, snap, paid, recv uint64) {
	casinoDay.Set(coin, strconv.FormatInt(day, 10)+":"+casU(snap)+":"+casU(paid)+":"+casU(recv))
}

func casinoIsOpen(coin string, pool uint64) bool {
	return pool >= casinoMinPoolUnits && casGrinValueMilli(coin, pool) >= casinoMinPoolMilli
}

func casinoMaxBet(game string, free uint64) uint64 {
	if game == "slots" {
		m := casMulDiv(free, slotsMaxBetPPM, 1000000)
		return m - m%slotsBetStep
	}
	return casMulDiv(free, casinoMaxBetBps, 10000)
}

// casinoCheckBet panics unless the pool can pay the bet's largest win in full (read-only).
func casinoCheckBet(coin, game string, amt uint64) {
	pool := casGet(&casinoPool, coin)
	reserved := casGet(&casinoReserved, coin)
	if !casinoIsOpen(coin, pool) {
		panic("casino closed for " + coin + ": the pool needs at least 20,000 grin-equivalent and 200 " + coin)
	}
	if game == "slots" && (amt < slotsBetStep || amt%slotsBetStep != 0) {
		panic("slots bet must be a multiple of 25")
	}
	free := casSub(pool, reserved)
	maxBet := casinoMaxBet(game, free)
	if amt > maxBet {
		if game == "slots" {
			panic("bet too large: slots max is 0.004 percent of the free casino pool (" + casU(maxBet) + " " + coin + ")")
		}
		panic("bet too large: max is 0.5 percent of the free casino pool (" + casU(maxBet) + " " + coin + ")")
	}
	exp := casinoExposure(game, amt)
	if casAdd(reserved, exp) > casMulDiv(pool, casinoOpenBps, 10000) {
		panic("casino busy: open bets on " + coin + " would exceed 20 percent of the pool")
	}
	_, snap, paid, recv := casinoDayState(coin)
	net := uint64(0)
	if paid > recv {
		net = paid - recv
	}
	if casAdd(casAdd(net, reserved), exp) > casMulDiv(snap, casinoDayBps, 10000) {
		panic("casino daily payout limit reached for " + coin)
	}
}

func casinoReserve(coin string, exp uint64) {
	casSet(&casinoReserved, coin, casAdd(casGet(&casinoReserved, coin), exp))
	day, snap, paid, recv := casinoDayState(coin)
	setCasinoDay(coin, day, snap, paid, recv)
}

// casinoSettle releases the reservation and moves coins: the player receives
// `payout` (0 ≤ payout ≤ stake + exposure) and the pool keeps the rest of the
// stake or pays the difference. Returns payout.
func casinoSettle(addr, coin string, amt, exposure, payout uint64) uint64 {
	if payout > casAdd(amt, exposure) {
		panic("payout above the reservation")
	}
	casSet(&casinoReserved, coin, casSub(casGet(&casinoReserved, coin), exposure))
	day, snap, paid, recv := casinoDayState(coin)
	pool := casGet(&casinoPool, coin)
	if payout >= amt {
		win := payout - amt
		casSet(&casinoPool, coin, casSub(pool, win))
		setCasinoDay(coin, day, snap, casAdd(paid, win), recv)
	} else {
		keep := amt - payout
		casSet(&casinoPool, coin, casAdd(pool, keep))
		setCasinoDay(coin, day, snap, paid, casAdd(recv, keep))
	}
	casCredit(addr, coin, payout)
	return payout
}

// SeedCasinoPool moves the ADMIN'S OWN on-chain coins into a casino pool.
// Only ever the admin's own balance; nobody can withdraw a pool back.
func SeedCasinoPool(cur realm, coinId string, amount string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	if _, ok := coinRarity[coinId]; !ok {
		panic("unknown coin id: " + coinId)
	}
	amt, err := strconv.ParseUint(amount, 10, 64)
	if err != nil || amt == 0 || amt > casinoMaxAmount {
		panic("invalid amount")
	}
	from := admin.String()
	casDebit(from, coinId, amt)
	casSet(&casinoPool, coinId, casAdd(casGet(&casinoPool, coinId), amt))
	casStat(coinId, "", "seeded", amt)
	chain.Emit("CasinoPoolSeeded", "coin", coinId, "from", from, "amount", amount)
}

// CasinoPool reports a coin's pool, reservation, max bets and daily counters.
func CasinoPool(coinId string) string {
	pool := casGet(&casinoPool, coinId)
	reserved := casGet(&casinoReserved, coinId)
	_, snap, paid, recv := casinoDayState(coinId)
	free := uint64(0)
	if pool > reserved {
		free = pool - reserved
	}
	return `{"coin":"` + coinId + `","pool":"` + casU(pool) + `","reserved":"` + casU(reserved) +
		`","maxBet":"` + casU(casinoMaxBet("coin_flip", free)) + `","slotsMaxBet":"` + casU(casinoMaxBet("slots", free)) +
		`","open":` + strconv.FormatBool(casinoIsOpen(coinId, pool)) +
		`,"daySnapshot":"` + casU(snap) + `","paidToday":"` + casU(paid) + `","receivedToday":"` + casU(recv) + `"}`
}

package game32

import (
	"strconv"
	"time"

	"chain"

	"gno.land/p/nt/avl/v0"
)

// ── Slots bonus features, all settled by the realm ──────────────────────────
//
// Free spins: 3/4/5 scatters on a paid spin grant 10/12/15 free spins at that
// spin's bet. The grant is a realm record (one open grant per player). The
// triggering spin keeps its 500× reservation for the whole feature, minus what
// it already paid, so every free spin can always be paid in full. A free spin is
// its own two-sided round (PlaceCasinoFreeSpin takes no stake); its wins are
// doubled, it pays from that reservation, scatters don't retrigger and vaults
// don't start Hold & Spin. The grant never expires for the player.
//
// Hold & Spin: 3+ vaults on a paid spin. Resolved inside that spin's settlement
// from the same seed stream (game_slots.gno). Coin tiles pay 1/2/3/5× the bet,
// MINI 20×, MINOR 75× (all under the 500× cap). The first MAJOR / GRAND tile
// pays that jackpot pool (extra ones pay as MINOR); a full board (20 tiles) also
// awards GRAND.
//
// MAJOR / GRAND jackpots: real pools per coin, fed with 1.0% / 0.5% of every
// paid slots stake (fractions carried exactly). A hit pays
// pool × min(1, bet / refBet); the rest stays. A pool can never pay more than
// it holds. After a hit the pool is topped back up to its reset seed from the
// house pool, only while the free house pool is ≥ 20× that top-up. The admin
// can add its own coins to a jackpot but nobody can withdraw one.

var (
	casinoGrants  avl.Tree // addr → *freeSpinGrant
	casinoJackpot avl.Tree // coin:tier → pool (string)
	casinoJpDust  avl.Tree // coin:tier → contribution remainder in bet×bps units (string)
	casinoJpSeed  avl.Tree // coin:tier → reset seed (string)
	casinoJpRef   avl.Tree // coin → reference bet (string)
)

const (
	freeSpinMult        = uint64(2)
	jpMajorBps          = uint64(100) // 1.0% of each paid slots stake
	jpGrandBps          = uint64(50)  // 0.5%
	jpDefaultRefBet     = uint64(100)
	jpResetFreeMultiple = uint64(20)
	hsMiniMult          = uint64(20)
	hsMinorMult         = uint64(75)
)

type freeSpinGrant struct {
	addr, coin string
	bet        uint64
	left       uint64
	total      uint64
	capLeft    uint64 // still reserved in casinoReserved for this feature
	won        uint64
	inRound    string
	fromRound  string
	grantedAt  int64
}

func getGrant(addr string) *freeSpinGrant {
	if !casinoGrants.Has(addr) {
		return nil
	}
	return casinoGrants.Get(addr).(*freeSpinGrant)
}

func jpKey(coin, tier string) string { return coin + ":" + tier }

func jpRefBet(coin string) uint64 {
	if v := casGet(&casinoJpRef, coin); v > 0 {
		return v
	}
	return jpDefaultRefBet
}

// casinoJackpotContribute moves 1.0% / 0.5% of a paid slots stake from the house
// pool into the MAJOR / GRAND pools (remainders carried, nothing rounded away).
func casinoJackpotContribute(coin string, amt uint64) {
	for _, t := range [2]struct {
		tier string
		bps  uint64
	}{{"major", jpMajorBps}, {"grand", jpGrandBps}} {
		k := jpKey(coin, t.tier)
		dust := casAdd(casGet(&casinoJpDust, k), casMul(amt, t.bps))
		units := dust / 10000
		if units == 0 {
			casSet(&casinoJpDust, k, dust)
			continue
		}
		pool := casGet(&casinoPool, coin)
		if pool < casAdd(casGet(&casinoReserved, coin), units) {
			casSet(&casinoJpDust, k, dust) // house can't spare it right now: keep it owed
			continue
		}
		casSet(&casinoJpDust, k, dust%10000)
		casSet(&casinoPool, coin, pool-units)
		casSet(&casinoJackpot, k, casAdd(casGet(&casinoJackpot, k), units))
		day, snap, paid, recv := casinoDayState(coin)
		setCasinoDay(coin, day, snap, casAdd(paid, units), recv)
	}
}

// casinoJackpotPay pays a jackpot tier to addr: pool × min(1, bet/refBet).
func casinoJackpotPay(addr, coin, tier string, bet uint64) uint64 {
	k := jpKey(coin, tier)
	pool := casGet(&casinoJackpot, k)
	ref := jpRefBet(coin)
	pay := pool
	if bet < ref {
		pay = casMulDiv(pool, bet, ref)
	}
	casSet(&casinoJackpot, k, pool-pay)
	casCredit(addr, coin, pay)
	chain.Emit("CasinoJackpotWon", "player", addr, "coin", coin, "tier", tier, "amount", casU(pay))
	// Top back up to the reset seed from the house pool, only if the house can easily afford it.
	seed := casGet(&casinoJpSeed, k)
	left := pool - pay
	if seed > left {
		need := seed - left
		house := casGet(&casinoPool, coin)
		reserved := casGet(&casinoReserved, coin)
		if house > reserved && house-reserved >= casMul(need, jpResetFreeMultiple) {
			casSet(&casinoPool, coin, house-need)
			casSet(&casinoJackpot, k, seed)
			day, snap, paid, recv := casinoDayState(coin)
			setCasinoDay(coin, day, snap, casAdd(paid, need), recv)
		}
	}
	return pay
}

// slotsHSPayout turns Hold & Spin tiles into bet multiples (under the cap) and
// the jackpot tiers won (paid from their pools).
func slotsHSPayout(tiles *[slotsCells]uint16, full bool) (uint64, bool, bool) {
	mult := uint64(0)
	major, grand := false, false
	for i := 0; i < slotsCells; i++ {
		v := tiles[i]
		switch {
		case v == 0:
		case v < 100:
			mult += uint64(v)
		case v == hsMini:
			mult += hsMiniMult
		case v == hsMinor:
			mult += hsMinorMult
		case v == hsMajor && !major:
			major = true
		case v == hsGrand && !grand:
			grand = true
		default: // a second MAJOR / GRAND in the same bonus pays as MINOR
			mult += hsMinorMult
		}
	}
	if full && !grand {
		grand = true
	}
	return mult, major, grand
}

// PlaceCasinoFreeSpin uses one free spin of the caller's grant in a committed
// round (no stake). One free spin in flight at a time.
func PlaceCasinoFreeSpin(cur realm, roundId string, clientHash string) {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	if isBlacklisted(caller) {
		panic("address banned")
	}
	r := mustCasinoRound(roundId)
	if r.player != caller {
		panic("this round belongs to another player")
	}
	if r.status != "committed" {
		panic("betting is closed for this round")
	}
	if time.Now().Unix()-r.committedAt >= casinoBetWindowSec {
		panic("round expired")
	}
	g := getGrant(caller)
	if g == nil || g.left == 0 {
		panic("no free spins left")
	}
	if g.inRound != "" {
		panic("a free spin is already in progress (round " + g.inRound + ")")
	}
	if !casIsHex64(clientHash) {
		panic("client hash must be sha256 hex")
	}
	g.inRound = roundId
	casinoBets.Set(roundId+":"+caller, &casinoBet{addr: caller, game: "slots", coin: g.coin, choice: "free", clientHash: clientHash, amount: g.bet, freeSpin: true})
	r.status = "bet"
	r.betAt = time.Now().Unix()
	r.bets = 1
}

// settleFreeSpin pays a free spin's win out of its grant's reservation.
func settleFreeSpin(b *casinoBet, win uint64) uint64 {
	g := getGrant(b.addr)
	if g == nil {
		panic("free spin grant missing")
	}
	if win > g.capLeft {
		win = g.capLeft
		b.capped = true
	}
	if win > 0 {
		casSet(&casinoReserved, b.coin, casSub(casGet(&casinoReserved, b.coin), win))
		casSet(&casinoPool, b.coin, casSub(casGet(&casinoPool, b.coin), win))
		day, snap, paid, recv := casinoDayState(b.coin)
		setCasinoDay(b.coin, day, snap, casAdd(paid, win), recv)
		casCredit(b.addr, b.coin, win)
	}
	g.capLeft -= win
	g.won += win
	g.left--
	g.inRound = ""
	if g.left == 0 {
		casSet(&casinoReserved, b.coin, casSub(casGet(&casinoReserved, b.coin), g.capLeft))
		casinoGrants.Remove(b.addr)
		chain.Emit("CasinoFreeSpinsDone", "player", b.addr, "coin", b.coin, "won", casU(g.won))
	}
	return win
}

// FreeSpinGrant reports a player's open free spins (null when none).
func FreeSpinGrant(addr string) string {
	g := getGrant(addr)
	if g == nil {
		return "null"
	}
	return `{"coin":"` + g.coin + `","bet":` + casU(g.bet) + `,"left":` + casU(g.left) + `,"total":` + casU(g.total) +
		`,"mult":` + casU(freeSpinMult) + `,"capLeft":` + casU(g.capLeft) + `,"won":` + casU(g.won) +
		`,"inRound":"` + g.inRound + `","fromRound":"` + g.fromRound + `"}`
}

// CasinoJackpots reports the real MAJOR / GRAND pools and how they pay.
func CasinoJackpots(coinId string) string {
	return `{"coin":"` + coinId + `","major":"` + casU(casGet(&casinoJackpot, jpKey(coinId, "major"))) +
		`","grand":"` + casU(casGet(&casinoJackpot, jpKey(coinId, "grand"))) +
		`","majorSeed":"` + casU(casGet(&casinoJpSeed, jpKey(coinId, "major"))) +
		`","grandSeed":"` + casU(casGet(&casinoJpSeed, jpKey(coinId, "grand"))) +
		`","refBet":"` + casU(jpRefBet(coinId)) + `","miniMult":` + casU(hsMiniMult) + `,"minorMult":` + casU(hsMinorMult) +
		`,"majorBps":` + casU(jpMajorBps) + `,"grandBps":` + casU(jpGrandBps) + `}`
}

func validJpTier(tier string) bool { return tier == "major" || tier == "grand" }

// SeedCasinoJackpot adds the ADMIN'S OWN coins to a jackpot pool (never withdrawable).
func SeedCasinoJackpot(cur realm, coinId, tier, amount string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	if _, ok := coinRarity[coinId]; !ok {
		panic("unknown coin id: " + coinId)
	}
	if !validJpTier(tier) {
		panic("tier must be major or grand")
	}
	amt, err := strconv.ParseUint(amount, 10, 64)
	if err != nil || amt == 0 || amt > casinoMaxAmount {
		panic("invalid amount")
	}
	casDebit(admin.String(), coinId, amt)
	k := jpKey(coinId, tier)
	casSet(&casinoJackpot, k, casAdd(casGet(&casinoJackpot, k), amt))
	casStat(coinId, "", "seeded", amt)
	chain.Emit("CasinoJackpotSeeded", "coin", coinId, "tier", tier, "amount", amount)
}

// SetCasinoJackpotSeed sets the level a jackpot is topped back up to after a hit.
func SetCasinoJackpotSeed(cur realm, coinId, tier, amount string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	if !validJpTier(tier) {
		panic("tier must be major or grand")
	}
	amt, err := strconv.ParseUint(amount, 10, 64)
	if err != nil || amt > casinoMaxAmount {
		panic("invalid amount")
	}
	casSet(&casinoJpSeed, jpKey(coinId, tier), amt)
}

// SetCasinoJackpotRefBet sets the bet that wins a full jackpot (smaller bets win
// the same share of the pool as their share of this bet).
func SetCasinoJackpotRefBet(cur realm, coinId, amount string) {
	if cur.Previous().Address() != admin {
		panic("unauthorized: admin only")
	}
	amt, err := strconv.ParseUint(amount, 10, 64)
	if err != nil || amt == 0 || amt > casinoMaxAmount {
		panic("invalid amount")
	}
	casSet(&casinoJpRef, coinId, amt)
}

package game32

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"chain"
)

// ── rounds ──────────────────────────────────────────────────────────────────

func getCasinoRound(id string) *casinoRound {
	if !casinoRounds.Has(id) {
		return nil
	}
	r, ok := casinoRounds.Get(id).(*casinoRound)
	if !ok {
		return nil
	}
	return r
}

func mustCasinoRound(id string) *casinoRound {
	r := getCasinoRound(id)
	if r == nil {
		panic("round not found")
	}
	return r
}

func casinoRoundBet(r *casinoRound, roundId string) *casinoBet {
	key := roundId + ":" + r.player
	if !casinoBets.Has(key) {
		return nil
	}
	return casinoBets.Get(key).(*casinoBet)
}

// CommitCasinoSeed opens a round for one player with sha256(s). Operator only;
// a round id can be used once.
func CommitCasinoSeed(cur realm, roundId string, player string, seedHash string) {
	if !isOperator(cur) {
		panic("unauthorized: casino operator only")
	}
	if !casSafe(roundId, 64) {
		panic("invalid round id")
	}
	if casinoRounds.Has(roundId) {
		panic("round already exists")
	}
	if !address(player).IsValid() {
		panic("invalid player address")
	}
	seedHash = strings.ToLower(seedHash)
	if !casIsHex64(seedHash) {
		panic("seedHash must be sha256 hex")
	}
	casinoRounds.Set(roundId, &casinoRound{player: player, seedHash: seedHash, status: "committed", committedAt: time.Now().Unix()})
}

// PlaceCasinoBet escrows the player's bet with sha256(c): only the round's
// player, only before s is revealed, and only if the pool can pay its largest win.
func PlaceCasinoBet(cur realm, roundId string, game string, coinId string, betAmount string, choice string, clientHash string) {
	requireNotPaused()
	caller := cur.Previous().Address().String()
	if isBlacklisted(caller) {
		panic("address banned")
	}
	r := mustCasinoRound(roundId)
	if r.player != caller {
		panic("this round belongs to another player")
	}
	if r.status != "committed" {
		panic("betting is closed for this round")
	}
	if time.Now().Unix()-r.committedAt >= casinoBetWindowSec {
		panic("round expired")
	}
	if _, ok := coinRarity[coinId]; !ok {
		panic("unknown coin id: " + coinId)
	}
	if !validCasinoChoice(game, choice) {
		panic("invalid game or choice: " + game + "/" + choice)
	}
	clientHash = strings.ToLower(clientHash)
	if !casIsHex64(clientHash) {
		panic("client hash must be sha256 hex")
	}
	amt, err := strconv.ParseUint(betAmount, 10, 64)
	if err != nil || amt == 0 || amt > casinoMaxAmount {
		panic("invalid bet amount")
	}
	if game == "slots" && getGrant(caller) != nil {
		panic("finish your free spins first")
	}
	// Check everything before any write, then debit and reserve the largest win.
	casinoCheckBet(coinId, game, amt)
	exp := casinoExposure(game, amt)
	casDebit(caller, coinId, amt)
	casinoReserve(coinId, exp)
	casinoBets.Set(roundId+":"+caller, &casinoBet{addr: caller, game: game, coin: coinId, choice: choice, clientHash: clientHash, amount: amt, exposure: exp})
	r.status = "bet"
	r.betAt = time.Now().Unix()
	r.bets = 1
}

// RevealCasinoSeed publishes s (it must hash to the commit). It settles nothing:
// the bet settles when the player's secret is revealed.
func RevealCasinoSeed(cur realm, roundId string, serverSeed string) {
	if !isOperator(cur) {
		panic("unauthorized: casino operator only")
	}
	r := mustCasinoRound(roundId)
	if r.status != "committed" && r.status != "bet" {
		panic("round already revealed or closed")
	}
	h := sha256.Sum256([]byte(serverSeed))
	if hex.EncodeToString(h[:]) != r.seedHash {
		panic("server seed does not match the committed hash")
	}
	r.serverSeed = serverSeed
	if r.status == "committed" {
		r.status = "closed" // no bet was placed: the round just ends
		return
	}
	r.status = "seeded"
	r.seededAt = time.Now().Unix()
}

// RevealCasinoSecret publishes the player's secret c (anyone may relay it: it
// must hash to the bet's hash) and settles the bet on chain. Works while paused.
func RevealCasinoSecret(cur realm, roundId string, clientSecret string) {
	r := mustCasinoRound(roundId)
	if r.status != "seeded" {
		panic("round is not waiting for the client secret")
	}
	b := casinoRoundBet(r, roundId)
	if b == nil || b.settled {
		panic("no open bet in this round")
	}
	if !casSafe(clientSecret, 64) {
		panic("invalid client secret")
	}
	if sha256Hex(clientSecret) != b.clientHash {
		panic("client secret does not match the bet's hash")
	}
	b.clientSecret = clientSecret
	casinoResolve(roundId, r, b)
	r.status = "settled"
}

// casinoResolve rolls the bet from s and c, pays it, and records the result.
func casinoResolve(roundId string, r *casinoRound, b *casinoBet) {
	payout := uint64(0)
	switch b.game {
	case "slots":
		s := newSlotsStream(r.serverSeed, b.clientSecret, roundId)
		g := slotsSpinGrid(s)
		mult, lines := slotsLineMult(&g)
		sc := slotsCount(&g, symScatter)
		win := casMul(b.amount/slotsBetStep, mult)
		if sc >= 3 {
			win = casAdd(win, casMul(b.amount, slotsScatterPay[sc]))
		}
		b.grid = slotsGridString(&g)
		b.lineMult = mult
		b.lines = lines
		b.scatters = sc
		if b.freeSpin {
			// ×2, no retrigger, no Hold & Spin; paid from the grant's reservation.
			payout = settleFreeSpin(b, casMul(win, freeSpinMult))
			b.payout = payout
			b.won = payout > 0
			b.outcome = "lose"
			if payout > 0 {
				b.outcome = "win"
			}
			b.settled = true
			casRecord(b.coin, "slots", 0, payout)
			casStat(b.coin, "slots", "freeSpins", 1)
			chain.Emit("CasinoBetSettled", "round", roundId, "player", b.addr, "game", "slots", "coin", b.coin,
				"amount", "0", "freeSpin", "true", "outcome", b.outcome, "won", strconv.FormatBool(b.won), "payout", casU(payout))
			return
		}
		major, grand := false, false
		if slotsCount(&g, symVault) >= 3 {
			tiles, played, full := slotsHoldAndSpin(s, &g)
			hm, mj, gr := slotsHSPayout(&tiles, full)
			b.hsTiles = hsTilesString(&tiles)
			b.hsRespins = played
			b.hsMult = hm
			major, grand = mj, gr
			win = casAdd(win, casMul(b.amount, hm))
		}
		capWin := casMul(b.amount, slotsMaxWinMult)
		if win > capWin {
			win = capWin
			b.capped = true
		}
		payout = casinoSettle(b.addr, b.coin, b.amount, b.exposure, win)
		if sc >= 3 {
			// The rest of this spin's 500× cap stays reserved for its free spins
			// (reserved before anything else leaves the pool, so pool ≥ reserved holds).
			n := slotsFreeSpins[sc]
			capLeft := capWin - win
			casinoReserve(b.coin, capLeft)
			casinoGrants.Set(b.addr, &freeSpinGrant{addr: b.addr, coin: b.coin, bet: b.amount, left: n, total: n, capLeft: capLeft, fromRound: roundId, grantedAt: time.Now().Unix()})
			b.fsGranted = n
			chain.Emit("CasinoFreeSpinsGranted", "player", b.addr, "coin", b.coin, "spins", casU(n), "bet", casU(b.amount))
		}
		casinoJackpotContribute(b.coin, b.amount)
		jw := uint64(0)
		if grand {
			jw = casAdd(jw, casinoJackpotPay(b.addr, b.coin, "grand", b.amount))
			b.jackpots = "grand"
		}
		if major {
			jw = casAdd(jw, casinoJackpotPay(b.addr, b.coin, "major", b.amount))
			if b.jackpots != "" {
				b.jackpots = "major+" + b.jackpots
			} else {
				b.jackpots = "major"
			}
		}
		b.jackpotWin = jw
		b.payout = casAdd(payout, jw)
		b.won = b.payout > b.amount
		b.outcome = "lose"
		if b.payout > 0 {
			b.outcome = "win"
		}
		b.settled = true
		casRecord(b.coin, "slots", b.amount, b.payout)
		chain.Emit("CasinoBetSettled", "round", roundId, "player", b.addr, "game", "slots", "coin", b.coin,
			"amount", casU(b.amount), "outcome", b.outcome, "won", strconv.FormatBool(b.won), "payout", casU(b.payout),
			"jackpots", b.jackpots, "freeSpins", casU(b.fsGranted))
		return
	case "rps":
		b.roll = CasinoRoll(r.serverSeed, b.clientSecret, roundId, b.game)
		res := CasinoOutcome("rps", b.roll)
		b.outcome = rpsHouseMove(b.choice, res)
		switch res {
		case "win":
			payout = casAdd(b.amount, b.amount)
			b.won = true
		case "push":
			payout = b.amount
		}
	default:
		b.roll = CasinoRoll(r.serverSeed, b.clientSecret, roundId, b.game)
		b.outcome = CasinoOutcome(b.game, b.roll)
		if b.outcome == b.choice {
			payout = casAdd(b.amount, b.amount)
			b.won = true
		}
	}
	b.payout = casinoSettle(b.addr, b.coin, b.amount, b.exposure, payout)
	b.settled = true
	casRecord(b.coin, b.game, b.amount, b.payout)
	chain.Emit("CasinoBetSettled", "round", roundId, "player", b.addr, "game", b.game, "coin", b.coin,
		"amount", casU(b.amount), "roll", casU(b.roll), "outcome", b.outcome, "won", strconv.FormatBool(b.won), "payout", casU(b.payout))
}

// RefundCasinoBet returns the stake only if s was never revealed and 30 minutes
// have passed since the bet. Never after s is revealed. Works while paused.
func RefundCasinoBet(cur realm, roundId string) {
	caller := cur.Previous().Address().String()
	r := mustCasinoRound(roundId)
	if r.status == "refunded" {
		panic("bet already settled")
	}
	if r.status != "bet" {
		panic("round already revealed: no refunds")
	}
	if r.player != caller {
		panic("no bet found for this round")
	}
	if time.Now().Unix()-r.betAt < casinoSeedTimeoutSec {
		panic("refund opens 30 minutes after the bet if the server seed is never revealed")
	}
	b := casinoRoundBet(r, roundId)
	b.settled = true
	b.refunded = true
	if b.freeSpin {
		// No stake was taken: the free spin goes back to the grant.
		if g := getGrant(caller); g != nil && g.inRound == roundId {
			g.inRound = ""
		}
	} else {
		casSet(&casinoReserved, b.coin, casSub(casGet(&casinoReserved, b.coin), b.exposure))
		casCredit(caller, b.coin, b.amount)
	}
	r.status = "refunded"
	chain.Emit("CasinoBetRefunded", "round", roundId, "player", caller, "amount", casU(b.amount))
}

// ForfeitCasinoBet settles a bet as a loss when s was revealed but the player's
// secret was not within 24 h (only the player could know the result). Anyone.
func ForfeitCasinoBet(cur realm, roundId string) {
	r := mustCasinoRound(roundId)
	if r.status != "seeded" {
		panic("round is not waiting for the client secret")
	}
	if time.Now().Unix()-r.seededAt < casinoSecretTimeoutSec {
		panic("forfeit opens 24 hours after the server seed is revealed")
	}
	b := casinoRoundBet(r, roundId)
	b.forfeited = true
	b.outcome = "forfeit"
	if b.freeSpin {
		b.payout = settleFreeSpin(b, 0) // the free spin is used, it wins nothing
		casRecord(b.coin, b.game, 0, 0)
	} else {
		b.payout = casinoSettle(b.addr, b.coin, b.amount, b.exposure, 0)
		casRecord(b.coin, b.game, b.amount, 0)
	}
	b.settled = true
	r.status = "settled"
	chain.Emit("CasinoBetForfeited", "round", roundId, "player", b.addr, "amount", casU(b.amount))
}

